    elif op == "XOR":
        gates.append(f"out{signal} = out{src1} ^ out{src2}")
    elif op == "NOT":
        gates.append(f"out{signal} = ~out{src1}")

    return signal

# Use a balanced multiplexer approach
# We have 65536 LUT values to choose from using 16 select bits (inputs 0-15)
# A multiplexer tree uses O(n log n) gates where n = 2^16

# Build base constants for each output bit
# For each of the 32 output bits, we build a separate mux tree

output_signals = [None] * 32

for out_bit in range(32):
    print(f"Building mux for output bit {out_bit}...", flush=True)

    # Create LUT constants for this bit
    # Instead of creating 65536 separate gates, we can batch them
    # But we need to be smart about it

    # Build a tree bottom-up
    # Level 0: 65536 leaf values
    current_values = []
