        val = (lut[addr] >> out_bit) & 1
        if val == 0:
            current_values.append(emit_gate("CONST_0"))
        else:
            current_values.append(emit_gate("CONST_1"))

    if out_bit == 0:
        print(f"  Created {len(current_values)} leaf gates", flush=True)

    # Build mux tree: each level halves the number of values
    for sel_bit in range(16):
        next_values = []
        for i in range(0, len(current_values), 2):
